import React from 'react';
import './Box.css';

const Box = ({ name, actions, onActionClick }) => {
  return (
    <div className="box">
      <h3>{name}</h3>
      <div className="actions">
        {actions.map((action, index) => (
          <button
            key={index}
            className="action-button"
            onClick={() => onActionClick(action.command)}
          >
            {action.label}
          </button>
        ))}
      </div>
    </div>
  );
};

export default Box;
